<script setup>
import { computed, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { templateModels, templateRows, maskValue } from '../../data/taskTemplates'
const models = ref(templateModels)
const mode = ref('list')
const selected = ref([])
const keyword = ref('')
const applied = ref('')
const business = ref('')
const source = ref('直连表')
const chosen = ref(null)
const fields = ref([])
const meta = reactive({name:'',table:'mart796.dim_2026cunl_zfkr_23lei_mbmx',database:'地市集市新库',owner:'crm运维平台',description:''})
const page = ref(1)
const jump = ref('')
const details = ref(null)
const view = ref('list')
const uploadInput = ref(null)
const uploadFile = ref(null)
function pickUpload(event) {
  const file = event.target.files?.[0]
  event.target.value = ''
  if (!file) return
  if (!/\.(csv|xlsx)$/i.test(file.name)) return ElMessage.warning('请选择CSV或Excel字段配置文件')
  uploadFile.value = {name:file.name,size:file.size}
}
function importConfig() {
  fields.value.slice(0,3).forEach((field,index)=>field.mask=['中间模糊','右模糊','全模糊'][index])
  uploadFile.value = null; ElMessage.success('上传成功')
}
const filtered = computed(()=>models.value.filter(r=>(!applied.value||r.name.includes(applied.value))&&(!source.value||r.source===source.value)&&(!business.value||r.business===business.value)))
const all = computed({get:()=>filtered.value.length>0&&selected.value.length===filtered.value.length,set:v=>selected.value=v?filtered.value.map(r=>r.id):[]})
const activeFields = computed(()=>fields.value.filter(f=>f.enabled))
function edit(row) {
  chosen.value=row; fields.value=structuredClone(JSON.parse(JSON.stringify(row.config))); Object.assign(meta,{name:row.name,owner:row.owner,table:row.table || 'mart796.dim_2026cunl_zfkr_23lei_mbmx',database:row.database || '地市集市新库',description:row.description || ''});mode.value='fields';page.value=1
}
function preview(row) {edit(row);mode.value='preview'}
function cancel() {mode.value='list';chosen.value=null;fields.value=[]}
function next() {if(!fields.value.some(f=>f.enabled))return ElMessage.warning('请至少选择一个使用字段');mode.value='preview';page.value=1}
function save() {
  if(!meta.name.trim())return ElMessage.warning('请输入表别名')
  chosen.value.config=structuredClone(JSON.parse(JSON.stringify(fields.value)));chosen.value.name=meta.name;chosen.value.owner=meta.owner;chosen.value.table=meta.table;chosen.value.database=meta.database;chosen.value.description=meta.description
  mode.value='list'; ElMessage.success('保存成功')
}
function search(){applied.value=keyword.value;selected.value=[]}
function no(text){ElMessage.info(text+'暂不可用')}
async function remove(row) {
 try {await ElMessageBox.confirm('确定删除该数据集吗？','询问',{confirmButtonText:'确定',cancelButtonText:'取消'})}catch{return}
 const index=models.value.findIndex(r=>r.id===row.id);if(index>=0)models.value.splice(index,1);selected.value=selected.value.filter(id=>id!==row.id);ElMessage.success('删除成功')
}
function download() {
 const csv='\ufeff'+[['字段名称','中文字段名称','字段模糊方式','是否使用'],...fields.value.map(f=>[f.name,f.label,f.mask,f.enabled?'是':'否'])].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n')
 const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='字段配置.csv';a.click();URL.revokeObjectURL(url)
}
function setPage(value){if(!Number.isInteger(Number(value))||Number(value)<1||Number(value)>369433)return ElMessage.warning('请输入有效页码');page.value=Number(value)}
</script>
<template>
<div class="nf-feature-10">
<template v-if="mode==='list'">
<div class="nf-model-filters"><span>过滤条件 <button class="nf-filter-pill" @click="source=''">数据来源类型：{{source||'全部'}}</button></span><form @submit.prevent="search"><select aria-label="搜索类型"><option>数据表</option></select><input v-model="keyword" aria-label="工作表名称" placeholder="请输入工作表名称查找..."/><button class="nf-search" aria-label="查询数据集">⌕</button><button type="button" class="nf-upload" @click="no('上传文件')">上传文件</button></form></div>
<div class="nf-model-options"><div><span>业务类型：</span><button v-for="city in ['景德镇','省公司','吉安','赣州','九江','南昌','萍乡','宜春','抚州','新余','上饶','鹰潭']" :key="city" :class="{active:business===city}" @click="business=business===city?'':city;selected=[]">{{city}}</button></div><div><span>数据来源类型：</span><button v-for="s in ['直连表','上传文件','二次处理']" :key="s" :class="{active:source===s}" @click="source=s;selected=[]">{{s}}</button></div></div>
<div class="nf-view-actions"><div><button aria-label="卡片视图" @click="view='cards'">▦</button><button aria-label="列表视图" @click="view='list'">☷</button></div><button class="nf-document" @click="details={name:'取数操作文档',description:'选择数据集后点击修改，配置字段并预览，确认后保存。'}">取数操作文档</button></div>
<div v-if="view==='list'" class="nf-model-table"><table><colgroup><col style="width:2%"/><col style="width:27.5%"/><col style="width:16.5%"/><col style="width:13.2%"/><col style="width:13.2%"/><col style="width:27.6%"/></colgroup><thead><tr><th><input v-model="all" :indeterminate="selected.length>0&&!all" type="checkbox" aria-label="全选数据集"/></th><th>中文表名称</th><th>更新时间</th><th>模型发布人</th><th>模型业务负责人</th><th>操作</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td><input v-model="selected" type="checkbox" :value="row.id" :aria-label="'选择'+row.name"/></td><td>{{row.name}}</td><td>{{row.updated}}</td><td>{{row.publisher}}</td><td>{{row.owner}}</td><td class="nf-model-ops"><button @click="preview(row)">查看</button> / <button @click="edit(row)">修改</button> / <button @click="no('共享')">共享</button> / <button @click="no('取数')">取数</button> / <button @click="no('仪表板')">仪表板</button> / <button @click="remove(row)">删除</button></td></tr><tr v-if="!filtered.length"><td colspan="6">暂无数据</td></tr></tbody></table></div>
<div v-else class="nf-model-cards"><article v-for="row in filtered" :key="row.id"><h3>{{row.name}}</h3><p>模型业务负责人：{{row.owner}}</p><button @click="edit(row)">修改</button></article></div>
</template>
<template v-else-if="mode==='fields'||mode==='basic'">
<div class="nf-model-steps"><div :class="{current:mode==='basic'}"><b>1</b> 数据库表新增</div><div :class="{current:mode==='fields'}"><b>2</b> 字段配置</div><div><b>3</b> 预览</div></div>
<form v-if="mode==='basic'" class="nf-basic" @submit.prevent="mode='fields'"><label>表别名<input v-model="meta.name" aria-label="表别名"/></label><label>数据库表名称<input v-model="meta.table" aria-label="数据库表名称"/></label><label>归属数据库<input v-model="meta.database" aria-label="归属数据库"/></label><label>模型业务负责人<input v-model="meta.owner" aria-label="模型业务负责人"/></label><button>下一步</button><button type="button" @click="cancel">取消</button></form>
<template v-else><div class="nf-field-config-scroll"><table class="nf-field-config"><colgroup><col style="width:47px"/><col style="width:180px"/><col style="width:195px"/><col style="width:255px"/><col style="width:80px"/><col style="width:100px"/><col style="width:103px"/><col style="width:156px"/><col style="width:103px"/><col style="width:104px"/><col style="width:103px"/><col style="width:123px"/><col style="width:154px"/><col style="width:120px"/></colgroup>
<thead><tr><th>列名称</th><th>字段名称</th><th>中文字段名称</th><th>指标分组</th><th>字段属性</th><th>字段类型</th><th>默认展现方式</th><th>维度设置</th><th>口径设置</th><th>字段模糊方式</th><th>设置字段含义</th><th>是否使用 (全选:<input aria-label="全部使用字段" type="checkbox" :checked="fields.every(f=>f.enabled)" @change="fields.forEach(f=>f.enabled=$event.target.checked)"/>)</th><th>仅展现默认筛选条件</th><th>服务名称</th></tr></thead>
<tbody><tr v-for="(field,index) in fields" :key="field.name"><td>{{index+1}}</td><td class="nf-field-name"><span>☞</span>{{field.name}}</td><td><input v-model="field.label" :aria-label="field.name+'中文字段名称'"/></td><td><select v-model="field.group" :aria-label="field.name+'指标分组'"><option>默认属性组</option><option>系统属性组</option></select></td><td><select v-model="field.attribute" :aria-label="field.name+'字段属性'"><option>维度</option><option>指标</option></select></td><td>{{field.type}}</td><td><select v-model="field.method" :aria-label="field.name+'默认展现方式'"><option>模糊查询</option><option>精确查询</option></select></td><td></td><td><button class="nf-mini" :aria-label="field.name+'口径设置'" @click="details={name:field.name+'口径设置',description:field.label}">▧</button><button class="nf-mini" :aria-label="field.name+'清除口径'" @click="ElMessage.success('已清除')">▤</button></td><td><select v-model="field.mask" :aria-label="field.name+'字段模糊方式'"><option>不模糊</option><option>左模糊</option><option>中间模糊</option><option>右模糊</option><option>全模糊</option></select></td><td><select v-model="field.meaning" :aria-label="field.name+'设置字段含义'"><option>--请选择--</option><option>日期</option><option>地市</option><option>用户标识</option></select></td><td><input v-model="field.enabled" type="checkbox" :aria-label="field.name+'是否使用'"/></td><td><input v-model="field.filterOnly" type="checkbox" :aria-label="field.name+'仅展现默认筛选条件'"/></td><td><input v-model="field.service" :aria-label="field.name+'服务名称'"/></td></tr></tbody></table></div>
<div class="nf-wizard-footer"><button class="nf-previous" @click="mode='basic'">上一步</button><button @click="download">下载</button><button @click="uploadInput.click()">上传</button><input ref="uploadInput" type="file" accept=".csv,.xlsx" aria-label="字段配置文件" hidden @change="pickUpload"/><button @click="next">下一步</button><button class="nf-previous nf-cancel" @click="cancel">取消</button></div></template>
</template>
<template v-else-if="mode==='preview'">
<div class="nf-template-preview">
<table class="nf-model-meta"><tbody><tr><th>数据源类型</th><td>数据库直连</td><th>归属数据库</th><td>{{meta.database}}</td><th>数据库表名称</th><td>{{meta.table}}</td></tr><tr><th>表别名</th><td>{{meta.name}}</td><th>日期字段</th><td></td><th>表类型</th><td>其他</td></tr><tr><th>分表存储类型</th><td>不是分表</td><th>分表存储字段</th><td></td><th>最近更新时间</th><td>2026-03-14 00:00:00</td></tr><tr><th>模型业务负责人</th><td>{{meta.owner}}</td><td colspan="4"></td></tr><tr><th>数据源描述</th><td colspan="5">{{meta.description}}</td></tr><tr><th>取数按钮</th><td><button @click="no('取数')">取数</button></td><td colspan="4"></td></tr></tbody></table>
<div class="nf-preview-data-scroll"><table class="nf-preview-data"><thead><tr><th></th><th v-for="f in activeFields" :key="f.name">{{f.label}}</th></tr></thead><tbody><tr v-for="(row,index) in page===1?templateRows:[]" :key="index"><td>{{index+1}}</td><td v-for="f in activeFields" :key="f.name">{{maskValue(row[f.name],f.mask)}}</td></tr><tr v-if="page!==1"><td :colspan="activeFields.length+1">暂无数据</td></tr></tbody></table></div>
<div class="nf-preview-pages"><span>共 3694323 条记录</span><nav><button :disabled="page===1" @click="setPage(page-1)">上一页</button><button v-for="n in 6" :key="n" :class="{active:page===n}" @click="setPage(n)">{{n}}</button><span>…</span><button @click="setPage(369433)">369433</button><button :disabled="page===369433" @click="setPage(page+1)">下一页</button>前往<input v-model="jump" aria-label="前往页码"/>页<button @click="setPage(jump)">确定</button></nav></div>
<div class="nf-preview-footer"><button @click="mode='fields'">上一步</button><button class="nf-primary" @click="save">保存</button><button @click="cancel">返回数据集管理</button></div>
</div>
</template>
<el-dialog :model-value="!!uploadFile" title="上传字段配置" width="500px" @close="uploadFile=null"><template v-if="uploadFile"><p>文件名称：{{uploadFile.name}}</p><p>文件大小：{{uploadFile.size}} 字节</p><p>字段数：9</p></template><template #footer><el-button @click="uploadFile=null">取消</el-button><el-button type="primary" @click="importConfig">确认导入</el-button></template></el-dialog>
<el-dialog :model-value="!!details" :title="details?.name" width="550px" @close="details=null">{{details?.description}}</el-dialog>
</div>
</template>
<style scoped>
